 mice:[['mouse_sid','Mouse SID','text',true],['physical_tag','Physical tag'],['manager','Manager','manager',true],['alternate_id','Alternate ID'],['sex','Sex','select',['Unknown','Male','Female']],['genotype','Genotype'],['mouseline','Mouseline'],['strain','Strain'],['generation','Generation'],['state','State','select',['Stock','Ended']],['status','Status'],['date_of_birth','Date of birth','date'],['wean_date','Wean date','date'],['cage_sid','Cage SID','cage'],['cage_tag','Cage tag'],['litter_sid','Litter SID'],['protocol','Protocol'],['sire_sids','Recorded sire IDs','ids'],['dam_sids','Recorded dam IDs','ids'],['end_date','End date','date'],['end_reason','End reason'],['comment','Comment','textarea']],
 matings:[['mating_sid','Mating SID','text',true],['mating_tag','Mating tag'],['state','State','select',['Active','Inactive']],['set_up_date','Set up date','date'],['cage_sid','Cage SID','cage'],['cage_tag','Cage tag'],['male_sids','Male member IDs','ids'],['female_sids','Female member IDs','ids'],['litter_mouseline','Litter mouseline'],['litter_strain','Litter strain'],['disbanded_date','Disbanded date','date'],['comment','Comment','textarea']],
